+
+  constructor(type: VCSType = 'git') {
+    this.type = type;
+  }
+
+  public async blameByFile(path: string): Promise<BlameResult> {
+    return this.getVCSBlamer()(path);
+  }
+
+  private getVCSBlamer(): (path: string) => {} {
+    if (this.type === 'svn') {
+      return svn;
+    }
+    return git;
+  }
+}

